"""Manually authored claims and research outcomes for the p4 shard.
Locator reuse is mechanical; mathematical decisions are explicitly authored below.
"""
from pathlib import Path
import json
OUT=Path(__file__).resolve().parents[1]
ITEMS={x['id']:x for x in json.loads((OUT/'items.json').read_text())}
claims=[]
DATES={
 'GIT':'Mumford first edition 1965; checked second edition 1982 and publisher history of third edition 1994. The retained reused typescript is undated; its priority is not inferred.',
 'SGA':'SGA 7 seminar 1967–1969; printed volume I, LNM 288, 1972. No date of first circulation of these individual leaves established.',
 'RAY':'Raynaud announcements 1967, full paper received 5 November 1969 and published 28 January 1970. Exact announcement numbering not recovered.',
 'HAAR':'Chabauty 1950; Bourbaki Intégration VII–VIII first edition 1963; exact date of retained draft no.384 not established.',
 'FORM':'Historical leaf undated. Modern comparison sources checked as of 19 November 2026; individual dates specified in fate.',
 'NOW':'Textual/algebraic check on 19 November 2026; no claimed date of first discovery.'}
def add(n,ins,status,cl,fate,refs,search,comp='No numerical computation is asserted; see proof audit for the structural check.',statement=None,present=None,confidence='high',date='NOW',quote=None,authorship='Grothendieck manuscript'):
 its=[ITEMS[f'SA13-{i}'] for i in ins];ls=[]
 for it in its:
  for l in it['lines']:
   if l not in ls:ls.append(l)
 claims.append(dict(id=f'C-SA13-{n}',items=[i['id'] for i in its],cote=sorted(set(x['cote'] for x in ls)),scans=list(dict.fromkeys(f"{x['cote']}:{x['scan']:03d}" for x in ls)),lines=ls,his_statement=quote if quote is not None else its[0]['his_words'],statement=statement or its[0]['statement'],status_on_pages=status,computation=comp,**{'class':cl},fate=fate,fate_date=DATES[date],present_status='As of 19 November 2026: '+(present or fate),refs=refs,confidence=confidence,search_ids=search,authorship=authorship))
N='code/computations.py; outputs/computations.txt; proof_audit.md'
add(400,[400],'proof sketched','B','The reused text matches Mumford–Fogarty GIT §1, Definition1.5 and the Reynolds-operator argument. Its hypothesis is linear reductivity, not merely reductivity in characteristic p. The identity follows from naturality for the G-linear multiplication map by an invariant element. Authorship of the reused printed result is Mumford’s, not established as new work by Grothendieck.',['P4_MumfordFogarty1982'],['P4-S01'],comp='proof_audit.md §1: G-linearity and natural projection; finite averaging illustration in '+N,date='GIT',authorship='Mumford source reused and annotated')
add(401,[401],'stated without proof','B','GIT §0, Propositions0.7–0.8 and the paragraph before Definition0.10 match the affineness/properness discussion. The group is reductive in that source’s setup, the geometric quotient is already given, stabilizers are finite, and properness means properness of the action graph. Missing preceding hypotheses on the retained leaf are recovered from this source, expressly as reconstruction.',['P4_MumfordFogarty1982'],['P4-S01'],date='GIT',authorship='Mumford source reused')
add(402,[402],'open on the pages','C','The margin asks whether flatness suffices in the stated equivalence-relation argument. Modern flat locally finitely presented equivalence relations have algebraic-space sheaf quotients under the standard representability hypotheses, but that is stronger data than an arbitrary orbit-space geometric quotient. GIT’s definition itself has a documented universal-submersiveness ambiguity. No exact theorem with all the margin’s missing hypotheses was identified.',['P4_MumfordFogarty1982','P4_HashimotoQuotients','P4_DeJongGIT'],['P4-S01','P4-S02'],confidence='medium',date='GIT',present='The precise flat replacement remains underdetermined by this excerpt; this is not evidence of an open modern representability theorem.')
add(403,[403],'proof sketched','B','GIT Proposition0.9 is the exact printed counterpart. Freeness there is the condition that G×X→X×X is a closed immersion; it is stronger than trivial stabilizers on geometric points. The margin’s smoothness/orbit-ideal warning concerns the local proof. The mature statement uses the established algebraic-group convention, and does not validate an arbitrary nonsmooth group-scheme reading.',['P4_MumfordFogarty1982'],['P4-S01'],date='GIT',authorship='Mumford proof with Grothendieck annotations')
add(404,[404],'open on the pages','B','The same footnote in the checked 1982 GIT edition says that algebraicity of Y is unnecessary, with a reference to Fogarty. Hashimoto’s primary paper states the finite-type conclusion for a universal strict orbit space under a flat finite-type group scheme over a noetherian base. These precise quotient hypotheses settle a modern version of the source’s expectation; an arbitrary locally ringed quotient is not covered.',['P4_MumfordFogarty1982','P4_HashimotoQuotients'],['P4-S01','P4-S02'],date='GIT',authorship='Mumford typed footnote, not assigned to Grothendieck')
add(405,[405],'stated without proof','A','SGA7 VIII1.1.4 and1.4 derive the Hom–Ext identification from the derived biextension interpretation VII3.6.5. If internal Hom(A,C)=0, the outer Ext terms vanish and automorphisms vanish; the sheaf-Hom condition must not be replaced by vanishing only of global Hom.',['P4_SGA7VII','P4_SGA7VIII'],['P4-S03'],comp='proof_audit.md §2: five-term sequence and automorphism calculation.',date='SGA')
add(406,[406],'stated without proof','A','SGA7 VII Remark2.9.6 gives precisely the equivalence between additivity of one parameter and factorization of the transposed parameter through internal Ext¹, under the pointed-map vanishing assumptions of2.9.4. The manuscript’s missing preceding hypotheses are material.',['P4_SGA7VII'],['P4-S03'],date='SGA')
add(407,[407],'stated without proof','A','SGA7 VII2.9.2–2.9.5 establishes rigidity and the special equivalence: for two abelian schemes and G_m, every birigidified invertible sheaf has its unique biextension structure. For general abelian sheaves there are explicit vanishing and additivity hypotheses. The words “dans des cas importants” are respected.',['P4_SGA7VII','P4_SGA7VIII'],['P4-S03'],date='SGA')
add(408,[408],'false as stated','B','The minus identity in the supplied text fails already at v=0 on the nonzero Néron–Severi class of an ample line bundle. The classical cube formula gives the plus identity and [n]*=n² on NS. A checked primary modern exposition gives the stronger Picard formula, Moonen et al. II(2.12). This identifies the mathematics but does not decide whether the minus is manuscript or transcription error.',['P4_MoonenLineBundles'],['P4-S04'],comp='Quadratic expansion and counterexample; '+N,date='NOW',present='Corrected quadratic identity established; literal transcribed identity refuted. No ink emendation made.')
add(409,[409],'proof sketched','C','The elementary splitting deduction is valid once a homomorphic lift s with h s=2id is supplied: n↦(n,s(n)) splits the pullback extension. Symmetric/antisymmetric decomposition of line bundles after inverting2 is classical, cf. Moonen II(2.12). The page’s unfinished formula and the exact claimed canonical sheaf-level lift over its unstated base were not identified as a fully matching published theorem.',['P4_MoonenLineBundles','P4_SGA7VII'],['P4-S03','P4-S04'],comp='proof_audit.md §2: pullback extension; formal scalar identities in '+N,date='SGA',present='Conditional algebraic implication checked; exact full functorial construction on this leaf remains incomplete.',confidence='medium')
add(410,[410],'false as stated','B','The literal intersection formula is set-theoretically false. The corrected identity uses U∪V; the proof’s finite-cover argument can instead use ⋃Δ_Ui⊂Δ_(⋂Ui). Bourbaki VIII§5 no.3 Proposition7 contains the mature compactness argument. This is reused Bourbaki material.',['P4_BourbakiIntegration78'],['P4-S05'],comp='Discrete Z, H=2Z, U={0,±2}, V={0,±3}; all neighborhoods open and relatively compact. '+N,date='HAAR',authorship='Bourbaki reused typescript')
add(411,[411],'proof sketched','B','Bourbaki VIII§5 no.3 Proposition6 matches the compact-generation recurrence and proves openness of the cocompact unimodular locus and continuity of quotient volume there. Without compact generation, G=⊕Z and its finite-rank direct summands converge to G while no quotient G/H_n is compact; this checks the need for the hypothesis.',['P4_BourbakiIntegration78'],['P4-S05'],comp='proof_audit.md §3: induction L^nK⊂KH and explicit Chabauty convergence counterexample.',date='HAAR',authorship='Bourbaki reused typescript')
add(412,[412],'stated without proof','B','The line is interrupted after “satis-”. The completion that Lie groups satisfy the no-small-discrete-subgroups condition follows from their no-small-subgroups theorem. Bourbaki VIII§5 no.4, following Theorem2, states the Lie-group example for a mature condition excluding small finite subgroups. The source’s exact unfinished word and stronger written discrete formulation are retained.',['P4_BourbakiIntegration78'],['P4-S05'],date='HAAR',authorship='Bourbaki reused typescript',confidence='medium')
add(413,[413],'proved there','B','The nonzero-vague-limit support argument matches Bourbaki VIII§5 no.1 Proposition1 and Lemmas1–3. For any locally compact G, nonzero positive Haar measures on varying closed subgroups form a closed set in the nonzero positive measures. The use of nets/filters is essential without countability.',['P4_BourbakiIntegration78'],['P4-S05'],comp='proof_audit.md §3 gives the support/subgroup and translation-invariance argument; no sequence reduction assumed.',statement='A nonzero vague limit of right Haar measures on closed subgroups of a locally compact group G is right Haar measure on a closed subgroup, namely its support.',date='HAAR',authorship='Bourbaki reused typescript')
add(414,[414],'stated without proof','C','Raynaud1970 supplies the Picard separation/divisor-kernel results behind this degree-one invariant-cycle sequence; SGA7 IX12.1 prints a curve specialization. The handwritten proof on65–71 handles the prime-to-p Kummer and index-one steps, then introduces a Brauer correction. No opened primary theorem was found with exactly every amended alternative (arbitrary n when k perfect or index prime to p) and the manuscript’s unlabelled cohomology topology. The p-primary version cannot be certified by citing the ℓ≠p étale result.',['P4_Raynaud1970','P4_SGA7IX'],['P4-S06','P4-S07'],comp='proof_audit.md §4 redoes the Picard/Kummer diagram and identifies the missing p-primary hypotheses.',date='RAY',confidence='medium',present='Prime-to-p mechanism and divisor terms matched; full amended finite-level quantifiers remain only partially identified, not declared false or open in modern literature.')
add(415,[415],'proof sketched','B','Raynaud1970 §6.1.3 and6.1.11 identify vertical Cartier divisors modulo the special fibre; local factoriality makes all component cycles Cartier. Smith reduction of the one-column multiplicity vector gives torsΓ=Z/gcd(d_i). This recovers the numerator missing on61 from65 and69, without changing the frozen text.',['P4_Raynaud1970'],['P4-S06'],comp='One-column Smith invariants and cyclic torsion examples in '+N+'; proof_audit.md §4.',date='RAY')
add(416,[416],'stated without proof','C','The index formula gcd(μ_i d_i) is supported by Raynaud’s multiplicity theory and SGA7 IX12.1 in the curve setting. The extra factorization as gcd(d_i)·gcd(μ_i) is not an arithmetic identity. The test (d_i)=(2,3), (μ_i)=(1,2) disproves the unrestricted numerical shortcut but is not a geometrically realized regular model. No opened theorem imposes the missing relation that would justify this insertion in the stated generality.',['P4_Raynaud1970','P4_SGA7IX'],['P4-S06','P4-S07'],comp='Gcd countertest, explicitly numerical rather than geometric: '+N,date='RAY',confidence='medium',present='Index interpretation matched in specified settings; inserted gcd factorization remains a high-weight reading/hypothesis alarm.')
add(417,[417],'stated without proof','B','Raynaud1970 Theorem6.4.1 identifies E(S)∩P^τ(S) with the torsion of E(S), under his cohomological-flatness or (N) hypotheses, and makes it cyclic under (N)*. This implies finiteness of the kernel involving P^0, but does not identify P^0 and P^τ in all dimensions. Therefore kerw is a cyclic subgroup of torsΓ, of order e|d; equality is a separate question.',['P4_Raynaud1970'],['P4-S06'],comp='proof_audit.md §4: P^0⊂P^τ and subgroup order; cyclic examples in '+N,date='RAY')
add(418,[418],'false as stated','E','For R≅Z/e, tensoring its presentation with Z_ℓ gives R⊗Z_ℓ≅Z/ℓ^{v_ℓ(e)}. The transcribed Z/ℓ formula fails for e=ℓ². Scan71 also substitutes d for the not-yet-identified order e. This is elementary module theory; the correction does not refute the surrounding invariant-cycle theorem.',['P4_Raynaud1970'],['P4-S06'],comp='Cyclic tensor calculation for e=4,8,9,12,18; '+N,present='Literal formula refuted; refined formula proved directly. The class E concerns elementary algebra, not a priority claim for this manuscript theorem.')
add(419,[419],'stated without proof','C','The obstruction is the Picard–Brauer descent obstruction over K, with restriction–corestriction annihilation by degrees of zero-cycles. The manuscript’s arbitrary-n extension is coherent only with flat Kummer cohomology and compatible transition maps. Raynaud supplies relevant Picard theory, but the exact four/five-term sequence with θ(n) and every inserted p-case was not located as a single matching published theorem.',['P4_Raynaud1970','P4_SGA7IX'],['P4-S06','P4-S07'],comp='proof_audit.md §4: degree annihilation and Kummer transition ×ℓ.',date='RAY',confidence='medium')
add(420,[420],'stated without proof','B','The earlier run correctly isolates an incomplete abstract inference: bounded exponent alone does not kill an inverse limit. For the actual Kummer–Brauer coefficient tower, transitions are multiplication by ℓ; a uniformly bounded ℓ-primary group has zero inverse limit under these maps. This is a repair of the logical justification, not a refutation of the geometric limit.',['P4_Raynaud1970'],['P4-S06','P4-S07'],comp='Constant Z/p identity tower versus ×p tower, and the coefficient diagram; '+N,authorship='Earlier-run diagnostic of a manuscript inference',present='Abstract counterexample and compatible-tower repair both checked.')
add(421,[421],'proof sketched','C','Taking the compatible inverse limit yields the manuscript’s ℓ-adic sequence once finite-level exactness, finite generation and the Brauer-transition assertion are established. The untwisted comparison requires ℓ≠p; μ_{p^ν} belongs to flat cohomology. Opened Raynaud/SGA sources do not certify the entire all-ℓ formulation merely by their familiar prime-to-p statements.',['P4_Raynaud1970','P4_SGA7IX'],['P4-S06','P4-S07'],comp='proof_audit.md §4: tensoring finite cyclic terms and vanishing of bounded ×ℓ obstruction towers.',date='RAY',confidence='medium')
add(422,[422],'proof sketched','C','The construction of a Kummer cover from divisibility of the whole special fibre gives the prime-to-p bound once connectedness and degree of the generic cover are checked. The retained argument itself changes d to the index d^t; these are equal only under additional conditions. Raynaud1970 and SGA7 IX12.1 support the multiplicity/index comparison but do not remove this notational discrepancy in the draft.',['P4_Raynaud1970','P4_SGA7IX'],['P4-S06','P4-S07'],comp='proof_audit.md §4: Kummer equation, divisor of uniformizer and degree divisibility.',date='RAY',confidence='medium')
add(423,[423],'proof sketched','B','A zero-cycle of degree1 annihilates the Picard–Brauer obstruction by restriction–corestriction and Bézout combination of degrees. The same degree argument forces d=1. Raynaud1970 §7 and SGA7 IX12.1(a) record the corresponding geometric index-one implications, with hypotheses on the family kept explicit.',['P4_Raynaud1970','P4_SGA7IX'],['P4-S06'],comp='Bézout/divisibility argument in proof_audit.md §4; sample gcd certificates in '+N,date='RAY')
add(424,[424],'proof sketched','B','For n invertible, the nth-root obstruction is controlled by étale Kummer theory; proper base change and henselian lifting give the needed root-lifting step, subject to the Picard representability assumptions used by the draft. Stacks0A48 independently confirms finite étale equivalence for proper schemes over henselian local rings. This does not prove a p-primary analogue.',['P4_Raynaud1970','P4_Stacks0A48'],['P4-S06','P4-S08'],comp='proof_audit.md §4 identifies the Kummer square and Pic^0 divisibility, and the places completeness is invoked.',date='RAY',confidence='medium')
add(425,[425],'corrected by himself later','B','The attempted injectivity arguments on67 and69 are cancelled; the live text appeals to Raynaud. The full published result is Raynaud1970 Theorem6.4.1, with E∩P^τ and the (N)/(N)* conditions. The exact short-note “th.3” numbering was not recovered and remains unverified rather than silently equated with a different theorem.',['P4_Raynaud1970','P4_Raynaud1967Announcements'],['P4-S06','P4-S07'],comp='proof_audit.md §4 separates the withdrawn proof from the verified published replacement.',date='RAY')
add(426,[426],'corrected by himself later','E','Applying n-torsion to 0→δ′→δ→δ″→0 produces 0→δ′[n]→δ[n]→δ″[n]→δ′/nδ′. Thus the relevant image is δ[n]/δ′[n], which need not be all δ″[n]. The self-correction is mathematically necessary; δ=Z/4, δ′=2Z/4, n=2 is an explicit witness.',['P4_Raynaud1970'],['P4-S06'],comp='Finite-group enumeration and long-exact sequence in '+N,present='Self-corrected quotient is valid; the dropped surjectivity is refuted by the displayed example.')
add(427,[427],'proof sketched','B','For a horizontal integral finite closure of a generic closed point in regular X over a trait, its degree is the intersection with the principal special fibre, a sum Σ d_i(C·D_i). Therefore d divides every zero-cycle degree. Raynaud1970 §7.1 and SGA7 IX12.1 contain the corresponding multiplicity/index theory. The margin’s possible removal of regularity is a separate question.',['P4_Raynaud1970','P4_SGA7IX'],['P4-S06'],comp='proof_audit.md §4: intersection-length equality and divisibility; gcd certificate in '+N,date='RAY')
add(428,[428],'open on the pages','C','Raynaud1970 Theorem6.4.1 gives E∩P^τ=torsE. The manuscript asks for the kernel of specialization to the full geometric NS, hence P^0 rather than P^τ. For curves P^τ=P^0 and the full cyclic kernel is described in §8.1.2; the higher-dimensional p-primary claim is not established by that citation. No exact modern resolution of that broader formulation was identified.',['P4_Raynaud1970','P4_SGA7IX'],['P4-S06','P4-S07'],date='RAY',confidence='medium',present='Curve case and numerical-equivalence/torsion formulation matched; unrestricted higher-dimensional equality is not certified and is not labelled a known open problem.')
add(429,[429],'open on the pages','B','The resolution-qualified route is superseded, for the precise Picard separation statements, by Raynaud1970 Theorem6.4.1 without resolution of singularities, under (N) or cohomological flatness. This does not make every strengthening of R=torsΓ true. The manuscript’s “proposition7(ii)” in a short announcement remains bibliographically unaligned.',['P4_Raynaud1970','P4_Raynaud1967Announcements'],['P4-S06'],date='RAY')
add(431,[431],'open on the pages','B','The proof step extends generic line bundles using Cartier closures. Raynaud1970 §6.1.11 explicitly separates Cartier divisors from cycles and makes their map bijective under local factoriality. Thus local factoriality is the exact visible weakening of regularity for this step; it is not a replacement for all hypotheses of the invariant-cycle theorem.',['P4_Raynaud1970'],['P4-S06'],date='RAY')
add(432,[432,437],'proof sketched','A','SGA7 IX Remark2.6(a) explicitly describes the arithmetic Frobenius-weight proof of the inclusion and explicitly says it does not furnish equality; IX Theorem2.4 proves equality using biextensions and Raynaud. This is an exact methodological publication match. The manuscript’s detailed noetherian adic-base formulation and its finite-presentation reduction are more explicit than the printed remark. The alternative strict-henselian proof on81 is cancelled in full.',['P4_SGA7IX','P4_SGA7VIII'],['P4-S09'],comp='proof_audit.md §5: weight separation, specialization, finite data and scope of the equality.',date='SGA')
add(433,[433],'stated without proof','B','Finite étale schemes lift uniquely over henselian pairs (Stacks09ZL), and finite étale covers of a proper henselian family are equivalent to those of the closed fibre (0A48). The manuscript additionally needs the appropriate finite étale component of ℓ^ν-torsion in a flat group scheme. Its flat-not-smooth hypotheses cannot simply be replaced by the smooth Néron case; the existence of that finite piece is part of the argument to check.',['P4_Stacks09ZL','P4_Stacks0A48','P4_SGA7IX'],['P4-S08','P4-S09'],date='SGA',confidence='medium')
add(434,[434],'proof sketched','A','The arithmetic proof is identified in SGA7 IX2.6(a). Over a finite field, the source tensor has Frobenius eigenvalue absolute values q² and q^{3/2}, whereas the target has q. Coprime annihilating polynomials imply an equivariant map is zero, without semisimplicity. The manuscript’s spectral argument is valid in this form.',['P4_SGA7IX'],['P4-S09'],comp='Bézout/intertwiner proof and illustrative exact matrices in '+N,date='SGA')
add(435,[435],'proof sketched','C','The printed IX2.6(a) announces reduction to finite residue fields and sufficiently general bases, but does not print every trait/normalization lemma used on74–77. The strategy is valid only after choosing a trait or dense specialization detecting the finite étale pairing; this is a finite-presentation/constructibility step, not a consequence of weight estimates alone. No independent exact published version of the entire adic argument was located.',['P4_SGA7IX','P4_Stacks09ZL'],['P4-S08','P4-S09'],date='SGA',confidence='medium')
add(436,[436],'proof sketched','C','Spreading each ℓ^ν-torsion level separately does not select one model for all ν. The draft’s repair is to descend finite-type group/filtration data and finite multiplication-by-ℓ maps, then iterate after one enlargement of the model. SGA7 IX2.6(a) confirms the general arithmetic route, not the full uniform descent lemma with its exact flatness conditions.',['P4_SGA7IX','P4_Stacks09ZL'],['P4-S08','P4-S09'],comp='proof_audit.md §5: quantifier audit and finite-generation/iteration argument.',date='SGA',confidence='medium')
add(438,[438],'proof sketched','A','SGA7 IX2.5 gives the polarized formulation of2.4. A polarization induces an isogeny of Tate modules; denominator clearing works because the pairing target is torsion free. Conversely use the product with the dual and its Poincaré polarization to recover the mixed pairing. Thus equivalence is after the relevant finite-index argument, not an unjustified integral isomorphism.',['P4_SGA7IX'],['P4-S09'],comp='proof_audit.md §5: polarization/isogeny denominator argument.',date='SGA')
add(439,[439],'stated without proof','A','The finite-level warning is compatible with the inverse-limit theorem: geometric ℓ^ν torsion can all become rational over a finite extension depending on ν, where its Weil pairing remains nonzero. This does not yield one extension containing a compatible full Tate system. The last K must be compared on the scan with the preceding K′; the text has not propagated the base change.',['P4_SGA7IX'],['P4-S09'],comp='proof_audit.md §5 and finite symplectic pairing example in '+N,date='SGA')
add(440,[440,441],'stated without proof','B','Raynaud1970 Proposition8.1.2 gives the divisor/intersection presentation and its kernel/component comparison under (N), cohomological-flatness refinements and the curve hypotheses. The manuscript’s βα omits u and is ill-typed; βuα appears explicitly on84. SGA7 IX12.1 is a related index-one specialization, not an exact substitute for all general weighted statements.',['P4_Raynaud1970','P4_SGA7IX'],['P4-S10'],comp='proof_audit.md §6 and exact weighted matrix examples in '+N,date='RAY')
add(442,[442],'stated without proof','B','Raynaud1970 Theorem8.1.4 gives the Néron property under local factoriality after strict henselization, plus perfect residue field or total multiplicity prime to p. The manuscript has restored these alternatives after deleting a weaker line. Finiteness of the component group uses the intersection rank and does not by itself imply the Néron mapping property.',['P4_Raynaud1970'],['P4-S10'],date='RAY')
add(443,[443],'proved there','B','The displayed weighted pairing has matrix D=diag(δ_i); λ and μ are transposes and D·u is the symmetric intersection matrix. This algebra is directly checked. Perfectness of the weighted ambient pairing fails if any δ_i is not a unit; the crossed-out “parfait” is therefore material. Bosch–Lorenzini2002 §§1–2 explains the corresponding integral-lattice comparison.',['P4_BoschLorenzini2002','P4_Raynaud1970'],['P4-S10'],comp='Weighted transpose and intersection symmetry symbolically and numerically in '+N,date='RAY')
add(444,[444,445],'proof sketched','B','For a finite-rank free lattice E and injective symmetric u:E→E* of finite cokernel, b(x̄,ȳ)=y(u_Q^{-1}x) modZ is a perfect symmetric discriminant pairing. The manuscript has reached this setup under δ_i=1 and d=1. Bosch–Lorenzini2002 §1 gives the lattice construction; §2 shows why weighted geometric lattices require a separate comparison.',['P4_BoschLorenzini2002'],['P4-S10'],comp='Well-definedness/perfectness proof, rank-one −ab/m and finite checks for m=2…9 in '+N,date='NOW')
add(446,[446],'stated without proof','B','SGA7 VIII7.1(b) defines the component-group obstruction pairing for extending biextensions; IX1.2–1.3 applies it to the Poincaré biextension. Bosch–Lorenzini2002 Theorem4.6 proves equality with the intersection pairing for a smooth proper geometrically connected curve with a K-rational point and a proper regular model over a strictly henselian DVR. Corollary4.7 gives prime-to-p perfectness and full perfectness when components are geometrically reduced. This exactly supports the corresponding scoped Jacobian claim, not unconditional perfection over imperfect k.',['P4_SGA7VIII','P4_SGA7IX','P4_BoschLorenzini2002'],['P4-S10'],date='SGA')
add(447,[447],'stated without proof','C','The two drafts organize admissible power-series subrings into a substitution category. Modern Weierstrass systems are a developed analogous framework, but impose division and fixed coefficient-field axioms absent here. Aschenbrenner–Srhir2024 §2.1 and Cluckers–Lipshitz2017 definitions give precise comparisons; neither establishes historical derivation from these leaves nor the equivalence of the author’s changing axiom lists.',['P4_AschenbrennerSrhir2024','P4_CluckersLipshitz2017'],['P4-S11'],date='FORM',confidence='medium')
add(449,[449],'open on the pages','C','Ordinary henselianity solves polynomial étale equations, whereas closure of a whole substitution family under arbitrary formal inverses is additional compatible multivariable data. Modern Weierstrass systems satisfy inverse-function properties under stronger division axioms. The exact implication f′⇒f under just the manuscript’s a–e was not located in the opened literature; its crossed-out equivalence is not reinstated.',['P4_Stacks09XI','P4_AschenbrennerSrhir2024','P4_CluckersLipshitz2017'],['P4-S11','P4-S12'],date='FORM',confidence='medium',present='Specific stronger systems are established; the abstract converse is not settled by this search, and is not asserted to be a recognized open theorem.')
add(450,[450],'stated without proof','B','The rings of algebraic power series over the prime field are the henselizations of the localized polynomial rings and form the basic algebraic Weierstrass system. Modern primary descriptions of such systems support closure under composition and implicit inverse functions. This supplies the example/minimal construction under the first draft’s local coefficient-field axioms; it does not prove the arbitrary-family converse.',['P4_AschenbrennerSrhir2024','P4_CluckersLipshitz2017','P4_Stacks09XI'],['P4-S11','P4-S12'],date='FORM')
add(451,[451],'proof sketched','E','In characteristic0 over a coefficient field, adjoining a time coordinate replaces x′=ξ(t,x) by the autonomous field ∂t+ξ. Formal coefficient recursion uniquely solves the ODE; the assertion that its solution remains in A is the stated flow axiom. The formal Frobenius literature supplies the ambient formal setting, not an automatic consequence of henselianity.',['P4_BolsinovZuev2009'],['P4-S13'],comp='Formal ODE recursion and autonomous-variable calculation in '+N,date='FORM')
add(452,[452],'stated without proof','C','The stated flow closure yields primitives and the displayed elementary formal solutions (log, exp, trigonometric functions). These are established formal ODE identities; algebraic power-series systems alone are not flow closed, since exp(t) is not algebraic in characteristic0. No publication of the exact smallest flow-closed A-family was identified in the searched Weierstrass/formal-Frobenius literature.',['P4_BolsinovZuev2009','P4_AschenbrennerSrhir2024'],['P4-S11','P4-S13'],comp='Taylor/ODE identities and an algebraic-independence proof for exponentials in '+N+'; proof_audit.md §7.',date='FORM',confidence='medium')
add(453,[453],'proof sketched','C','Formal Lie theory establishes BCH integration in characteristic0, but the manuscript claims membership in its particular A-family and stops after an Ado reduction. Formal Frobenius gives a related integrable formal subgroup construction, not by itself every required A-descent assertion. No exact publication under precisely these axioms was identified. In particular evaluation of a formal time parameter at1 is unavailable without additional justification.',['P4_BolsinovZuev2009','P4_CluckersLipshitz2017'],['P4-S13','P4-S14'],comp='Class-two BCH associativity identity in '+N+' is an illustration only; it does not certify general A-membership.',date='FORM',confidence='medium')
add(454,[454,455],'open on the pages','C','Bolsinov–Zuev2009 Theorem2 proves the formal Frobenius theorem for constant-rank involutive distributions over any characteristic-zero field. The page asks for its solution inside A and makes this an extra axiom; rank1 is linked to flow closure. The full formal theorem does not settle the abstract A-closure requirement. The retraction/product draft on39:8 is wholly cancelled.',['P4_BolsinovZuev2009','P4_CluckersLipshitz2017'],['P4-S13'],date='FORM',confidence='medium')
add(456,[456],'stated without proof','E','For the (t)-adic topology on k[[t]], continuous substitution is defined when the finitely many input constant terms are nilpotent. Their generated ideal is nilpotent, so each output coefficient receives only finitely many contributions at a fixed adic order. Substituting1 fails already for Σt^n. Formal-scheme references verify the ambient nilpotent-point convention.',['P4_StricklandFormal','P4_StricklandFPFP'],['P4-S15'],comp='Nilpotent substitution coefficient check over Z/8 and proof in '+N,date='FORM')
add(457,[457],'open on the pages','C','The text asks to extend the theory to projective modules, perhaps finite modules. Formal affine spaces attached to finite projective modules are coordinate-free and smooth; arbitrary finite modules need not be locally free and yield singular/non-smooth objects. Strickland’s formal schemes provide a broader framework, but no exact development of this manuscript’s A-structures on arbitrary finite modules was identified.',['P4_StricklandFormal'],['P4-S15','P4-S11'],comp='proof_audit.md §7: module/projectivity distinction; no arbitrary-finite descent theorem is claimed.',date='FORM',confidence='medium')
add(458,[458],'stated without proof','C','The transverse fibre-product construction is standard once an implicit-function/inverse-closure axiom is available. It is asserted before H in the ring draft, so under the earlier a,b,c alone its proof has a missing dependency. Chiu–Hauser Lemma1.2 verifies the ambient formal inverse criterion, but not closure in an arbitrary selected subring family.',['P4_ChiuHauser2021'],['P4-S12','P4-S15'],comp='proof_audit.md §7: augmented Jacobian block and H dependence.',date='FORM',confidence='medium')
add(459,[459],'corrected by himself later','B','The evaluation-at1 proof is expressly rejected by the author because1 is not nilpotent. H yields g=f^{-1}s∈A_{n+1}; with divided-derivative closure D, taking D_sg at s=0 gives f^{-1}∈A_n. The repair uses legal evaluation at0 and exactly the differential hypothesis added in the margin.',['P4_ChiuHauser2021','P4_Stacks09XD'],['P4-S12','P4-S15'],comp='Triangular inverse/coefficient extraction identities in '+N,date='FORM')
add(460,[460],'proof sketched','B','H alone implies (A_n,A_n∩(t)) is a Zariski pair: invert the map (t,s)↦(t,(1+h(t))(1+s)−1) and evaluate its last inverse component at0. It does not force inversion of every element whose constant is a unit in k: k=Q, A0=Z, A_n=Z+(t)Q[[t]] is substitution- and inverse-closed but2 is not a unit. This new counterexample distinguishes the weaker live consequence from the stronger differential repair.',['P4_Stacks09XD','P4_ChiuHauser2021'],['P4-S12','P4-S15'],comp='Full family hypothesis check in proof_audit.md §7 and symbolic inverse in '+N,date='NOW',present='Zariski-pair consequence proved; strong H-only unit reflection refuted with every basic family/H hypothesis checked.')
add(461,[461],'proof sketched','B','The factor-lifting argument is a standard henselian-pair characterization. Center the coefficient variables of monic factors; the Jacobian is the Sylvester resultant, a unit for coprime residue factors. H then lifts the factorization. Stacks09XD Definition15.11.1 and09XI give the exact henselian-pair formulations. The arbitrary-ring formulation requires comaximal factors and the Jacobson-radical condition, not a hidden locality assumption.',['P4_Stacks09XD','P4_Stacks09XI'],['P4-S12'],comp='Symbolic Sylvester/Jacobian determinant and proof in '+N,date='FORM')
add(462,[462],'proved there','B','The map (t,z)↦(t,P(t,z)) has invertible Jacobian under the stated derivative hypothesis. Inverting it by H and setting the last coordinate to0 gives the unique implicit solution in A_n. Chiu–Hauser Lemma1.2 verifies the ambient inverse theorem. The manuscript uses a legal zero substitution here, in contrast to the rejected unit proof.',['P4_ChiuHauser2021'],['P4-S12'],comp='Formal implicit example and general block-Jacobian proof in '+N,date='FORM')
add(463,[463],'open on the pages','C','If the ambiguous d means only differential closure, Q[t]⊂Q[[t]] disproves faithful flatness: the nonzero module Q[t]/(1−t) becomes0. If d means the henselian/inverse axiom, this counterexample does not apply. Modern Weierstrass systems have stronger noetherian/completion hypotheses supporting faithful flatness; they do not settle the author’s arbitrary-family question.',['P4_AschenbrennerSrhir2024','P4_CluckersLipshitz2017','P4_Stacks09XD'],['P4-S11','P4-S12'],comp='Geometric-series unit check and nonzero quotient certificate in '+N,date='FORM',confidence='medium')
add(464,[464],'stated without proof','C','Hasse operators, rather than ordinary derivatives, are the characteristic-free coefficient operators. Over a Q-algebra the two closure conditions coincide. Merely saying “characteristic0” after replacing the field by an arbitrary ring does not itself justify division by factorials. The example Z[t,t²/2] shows the ordinary-derivation argument is insufficient, but is not asserted to satisfy all multivariable substitution/H axioms. The margin therefore remains a scope alarm, not a full-system counterexample.',['P4_CluckersLipshitz2017'],['P4-S11','P4-S15'],comp='D² versus HasseD2 on t²/2 and characteristic-p derivative test in '+N,date='FORM',confidence='medium')
add(465,[465],'stated without proof','C','The coordinate Taylor formula supplies principal parts over a D-stable A-family; the construction then requires compatibility under A-coordinate changes and transverse pullback. This is standard in ordinary formal geometry, but no exact printed treatment of all the manuscript’s A-structures was located. The replacement “submersif” must be retained.',['P4_StricklandFormal','P4_CluckersLipshitz2017'],['P4-S11','P4-S15'],comp='Taylor/Hasse coefficient formula and composition coefficients in '+N+'; proof_audit.md §7.',date='FORM',confidence='medium')
add(466,[466],'proved there','B','For f=Σa_αt^α∈A_n, a_α=ε(D_αf)∈A0. Thus D and zero-substitution imply coefficient descent to A0; H alone does not, as Z+(t)Q[[t]] shows. This is a direct algebraic consequence, independently rechecked; the literature comparison is with coefficient-fixed Weierstrass systems, which build it into their setup.',['P4_AschenbrennerSrhir2024'],['P4-S11','P4-S15'],comp='Hasse coefficient extraction identities in '+N,date='NOW')
add(467,[467],'proof sketched','C','Using an A-transverse chart whose restriction to Y is formally invertible, H transports and uniquely determines any induced A-structure. The graph criterion follows by using the projection of the graph. The result is established locally under these chart/H assumptions; the page’s assertion of availability of such charts over arbitrary bases needs the projective-module/locality scope to be supplied. No exact global theorem for the author’s whole category was found.',['P4_ChiuHauser2021','P4_StricklandFormal'],['P4-S12','P4-S15'],comp='proof_audit.md §7: two-chart comparison and graph projection.',date='FORM',confidence='medium')
add(468,[468],'stated without proof','C','A smooth scheme with section over O_A(X) has a locally power-series formal completion; implicit inversion transports an A-structure in a chosen smooth chart. Functorial gluing and arbitrary-base projective tangent modules are extra checks. Strickland formal-scheme constructions and the formal inverse theorem support these local pieces, not an exact publication match for the entire claimed A-functor.',['P4_StricklandFormal','P4_ChiuHauser2021'],['P4-S12','P4-S15'],date='FORM',confidence='medium')
add(469,[469],'proof sketched','C','The transverse-section argument gives uniqueness of a quotient A-structure when it exists; the displayed criterion has domain X, not an unexplained X′. Ambient formal submersions admit local sections and charts. Existence of a quotient A-structure for an A-relation is separately imposed by the integral axiom and is not proved by this uniqueness argument.',['P4_StricklandFormal','P4_BolsinovZuev2009'],['P4-S13','P4-S15'],comp='proof_audit.md §7: retraction and coordinate transport.',date='FORM',confidence='medium')
add(470,[470],'open on the pages','C','Formal smooth equivalence relations/submersive quotients and characteristic-zero regular foliations have established ambient formalisms. The manuscript makes descent of an A-structure through such a relation an extra axiom. Formal Frobenius (Bolsinov–Zuev Theorem2) proves existence of formal first integrals, not their membership in an arbitrary A-family. No exact development of this particular integral axiom was identified.',['P4_BolsinovZuev2009','P4_StricklandFormal'],['P4-S13','P4-S15'],date='FORM',confidence='medium')
add(471,[471],'proof sketched','B','The arbitrary complete separated linearly topologized-ring statement is matched by Strickland’s preliminary FPFP Theorem33.1/Corollary33.2, whose formal-ring definition is completeness for ideals. The discrete nilpotent case is Lemma5.14/Corollaries5.15–5.16 of Formal schemes and formal groups. O’Malley1972 Theorem2.10 covers the adically complete case, traced backwards from Moret-Bailly2023 §1.2; its original text was not accessible here. The scalar α in the final manuscript line must be the full unit series U for general F.',['P4_StricklandFPFP','P4_StricklandFormal','P4_MoretBailly2023','P4_OMalley1972'],['P4-S16'],comp='Complete finite-filtration proof and nilpotent-ring division example in '+N,date='FORM',present='Stated theorem established in its full linear-topology scope; proof repaired by retaining the full unit series, without altering the transcription.')

# Subsidiary assertions not collapsed into the preceding main results.
add(472,[400],'stated without proof','B','The retained opening is GIT Theorem1.1: a linearly reductive affine algebraic group acting on an affine k-scheme has an affine categorical quotient with the usual invariant-ring properties. Only its beginning is present; source context, not the unfinished leaf, supplies its full statement.',['P4_MumfordFogarty1982'],['P4-S01'],statement='For an affine k-scheme X with a linearly reductive affine algebraic group action, the invariant-ring morphism X→Spec(k[X]^G) is the affine categorical quotient; finite-type conclusions require finite type of X.',date='GIT',authorship='Mumford reused typescript')
add(473,[401],'stated without proof','B','The matched GIT paragraph states reductivity of stabilizers for affine geometric quotients in characteristic0 and cites an Iwahori-type criterion; the retained bibliography slot is blank. The exact bibliography number in the final edition differs. The assertion is classical in its affine homogeneous-space setting, but the missing Iwahori item has not been individually verified.',['P4_MumfordFogarty1982'],['P4-S01'],statement='In the characteristic-zero affine geometric-quotient setting of the source, closed-orbit stabilizers are reductive. This is not a claim about all stabilizers in arbitrary affine representations.',date='GIT',confidence='medium',authorship='Mumford reused typescript')
add(474,[413],'proof sketched','B','Bourbaki VIII§5 no.1 Proposition2 is the exact normalized-slice compactness result. A positive test function nonzero at e bounds the mass in one neighborhood; finite translates bound the mass of every compact set, giving vague compactness.',['P4_BourbakiIntegration78'],['P4-S05'],statement='For φ∈C_c(G), φ≥0 and φ(e)>0, the set of positive right Haar measures α on closed subgroups with α(φ)=1 is vague compact.',comp='proof_audit.md §3: local mass bound and finite covering.',date='HAAR',authorship='Bourbaki reused typescript')
add(475,[413],'proof sketched','B','Bourbaki VIII§5 no.2 Proposition4 identifies the lower semicontinuity of quotient volume on the unimodular-subgroup Haar-measure locus. The general ambient group is locally compact; fixed right Haar measure and the quotient measure convention are part of the statement.',['P4_BourbakiIntegration78'],['P4-S05'],statement='For fixed right Haar measure μ on locally compact G and α a right Haar measure on a closed unimodular subgroup, α↦‖μ/α‖ is lower semicontinuous for vague convergence.',date='HAAR',authorship='Bourbaki reused typescript')
add(476,[413],'proof sketched','B','Bourbaki VIII§5 no.2 Proposition5 completes the source proof that continues off-page. An integrable g whose periodization is ≥1 uniformly bounds quotient volumes; compact approximation then gives upper semicontinuity, combined with Proposition4.',['P4_BourbakiIntegration78'],['P4-S05'],statement='On Γ⁰(g)={α:∫_H g(xs)dα(s)≥1 for every x}, with nonnegative μ-integrable g and H unimodular, quotient volume is continuous.',date='HAAR',authorship='Bourbaki reused typescript')
add(477,[410,413],'proof sketched','B','Bourbaki VIII§5 no.3 Proposition7 proves compactness of normalized uniformly discrete Haar measures, their neighborhood-cover property, and the uniform-avoidance criterion for relative compactness. Its continuous image gives compactness of the corresponding closed subgroups. The false displayed intersection identity is not needed.',['P4_BourbakiIntegration78'],['P4-S05'],statement='Normalized counting Haar measures of discrete H with H∩U={e} form a compact set; the entire space of normalized discrete Haar measures is locally compact, and relative compactness is equivalent to one common identity-avoidance neighborhood.',comp='proof_audit.md §3: compact slice, semicontinuity, neighborhood comparison and corrected finite-cover inclusion.',date='HAAR',authorship='Bourbaki reused typescript')
add(478,[408],'proof sketched','B','The multiplication formula is the classical corollary of the theorem of the cube, explicitly checked in Moonen II(2.12). On the Néron–Severi quotient inversion acts trivially, so the two Picard exponents add to n².',['P4_MoonenLineBundles'],['P4-S04'],statement='For an abelian variety A and a line bundle L, [n]*L≅L^{n(n+1)/2}⊗([-1]*L)^{n(n−1)/2}; hence [n]* acts as n² on NS(A).',comp='Exponent and quadratic identities in '+N,date='NOW')
add(479,[416,423,427],'stated without proof','B','Raynaud’s index/multiplicity theory is recalled in SGA7 IX12.1: d_i^t=μ_i d_i and d^t=gcd_i d_i^t; the index-one condition is equivalent to the existence of a degree-one zero-cycle under the curve/local-factorial hypotheses. This verified scoped result is separated from the questionable gcd factorization and from higher-dimensional extensions.',['P4_Raynaud1970','P4_SGA7IX'],['P4-S06','P4-S07'],statement='For the proper locally factorial relative curve over a strictly local trait in SGA7 IX12.1, total multiplicities d_i^t=μ_i d_i have gcd d^t; d^t=1 iff there is a zero-cycle of degree1 on the generic fibre.',date='RAY')
add(480,[442],'stated without proof','B','Raynaud1970 §8.1.2 computes the component quotient by the intersection map; the rank-r−1 intersection form makes it finite. This algebraic finiteness statement requires local factoriality to identify the divisor lattice and is distinct from the additional Néron assertion.',['P4_Raynaud1970'],['P4-S10'],statement='For the curve model and Cartier component-lattice hypotheses on83, coker(u) is finite, while ker(u) is the indicated finite cyclic vertical kernel.',comp='Rank-one discriminant and rank-two intersection examples in '+N,date='RAY')
add(481,[443,444],'proved there','B','With all δ_i=1, the annihilator of the multiplicity vector identifies E* with Hom(E,Z). If also gcd(d_i)=1, E is free and the pairing is perfect; symmetry of u then gives the discriminant pairing. This is integral lattice algebra, independently checked, and is the framework of Bosch–Lorenzini §1.',['P4_BoschLorenzini2002'],['P4-S10'],statement='For E=Z^r/Z(d_i), E*=ker(Σd_i·):Z^r→Z is the integral dual; E is free exactly when gcd(d_i)=1. The unweighted pairing is then perfect.',comp='Smith invariants and exact lattice proof in '+N,date='NOW')
add(482,[447,448],'stated without proof','E','The first draft’s a,b alone generate the prime ring as constants. Adding reflection of units into the subrings generates the prime field when k is a field. These are elementary minimality calculations; the S_n versus A_n reading in the unit axiom is decisive. Modern Weierstrass definitions fix the coefficient field at the outset and therefore do not diagnose this manuscript ambiguity.',['P4_AschenbrennerSrhir2024'],['P4-S11'],statement='For a field k, the minimal unital constant family is the image of Z; after adding unit-reflection it is the prime field. This claim uses the A_n reading in axiom c.',comp='proof_audit.md §7: minimal constants and field localization.',date='NOW')
add(483,[447],'false as stated','E','The minimum under a,b,d without the unit axiom is prime-ring polynomials, not prime-field polynomials in characteristic0. Taking k=Q and A_n=Z[t_1,…,t_n] satisfies the written a,b,d and does not contain1/2. The deleted c label may be decisive on the scan. With c retained, the localized prime-field polynomial family is correct.',['P4_AschenbrennerSrhir2024'],['P4-S11'],statement='Literal first-draft minimum P[t] under a,b,d is false for char0 if P denotes the already defined prime field; the corrected minimum is Im(Z→k)[t]. Under a,b,c,d the minimum is P[t]_(t).',comp='Full hypothesis check and 1/2 nonmembership in proof_audit.md §7.',date='NOW')
add(484,[447,456],'stated without proof','B','Closure under allowed substitution and inclusion of coordinates give identities, composition and products in the category of formal polydiscs. The ring condition makes substitution act on A-functions, using constants and the augmentation. This is the basic framework also used in modern Weierstrass/analytic structures, but the two manuscript axiom labelings are not literally identical.',['P4_CluckersLipshitz2017','P4_StricklandFormal'],['P4-S11','P4-S15'],statement='The chosen A-morphisms form a category with finite products once coordinate, ring and continuous-substitution axioms are imposed; their pullbacks preserve the A_n subrings.',comp='proof_audit.md §7: identity/composition/ring operations.',date='FORM')
add(485,[465],'stated without proof','C','D-stability gives an A-coefficient model for differential operators in a chart; composition follows from Hasse product and binomial identities. Functorial coordinate changes and relative smooth charts are needed to globalize. No exact source was located for all the author’s arbitrary-A assertions; ordinary formal-scheme differential theory is an established comparison.',['P4_StricklandFormal','P4_CluckersLipshitz2017'],['P4-S11','P4-S15'],statement='The duals of finite principal-parts algebras carry A-structures, their composition preserves A-differential operators, and these operators preserve A-functions, including the relative submersive case.',comp='Hasse composition D_aD_b=binomial(a+b,a)D_(a+b), product rule and truncation checks in '+N,date='FORM',confidence='medium')
add(486,[465],'stated without proof','C','For an A-smooth embedding with an A-transverse chart, truncated normal neighborhoods are built from the coordinate ideal and coefficient rings; transverse base change preserves that description. The manuscript leaves this as a general functorial construction. No exact publication of this A-family formulation was found; ordinary formal smooth geometry is insufficient to certify its full scope.',['P4_StricklandFormal','P4_ChiuHauser2021'],['P4-S12','P4-S15'],statement='Infinitesimal neighborhoods O_X/J^n of an A-smooth formal subspace admit canonical A-structures compatible with transverse pullback, under the requisite coordinate/H/D hypotheses.',date='FORM',confidence='medium')
add(487,[471],'stated without proof','B','Dividing Z^N by F gives a monic degree-N polynomial P in the ideal(F), with topologically nilpotent lower coefficients; the quotient factor is a unit. Strickland FPFP Corollary33.2 and Formal schemes Corollary5.16 establish this. The factorization is a consequence of the division theorem and is identified as our/earlier-note deduction where not separately stated on the leaf.',['P4_StricklandFPFP','P4_StricklandFormal','P4_MoretBailly2023'],['P4-S16'],statement='Under C-SA13-471, F=UP uniquely with U∈A[[Z]]× and P monic of degreeN whose lower coefficients are topologically nilpotent.',comp='Finite nilpotent-ring preparation example and general deduction in '+N,date='FORM',authorship='Mathematical consequence drawn from manuscript division theorem')
add(488,[447,456,462],'stated without proof','B','Chiu–Hauser2021 Lemma1.2 proves the formal inverse criterion over any commutative ring for zero constant terms. Finitely many nilpotent constants extend the criterion by nilpotent perturbation and completion. This verifies the ambient equivalence in the definition of H, not automatic inverse closure of A.',['P4_ChiuHauser2021','P4_StricklandFormal'],['P4-S12','P4-S15'],statement='A continuous k-algebra endomorphism of k[[t_1,…,t_n]] with nilpotent constant terms and Jacobian determinant at0 a unit is a formal automorphism; with zero constants this is the usual inverse-function criterion.',comp='proof_audit.md §7: degree induction and finite nilpotent translation; explicit inverse in '+N,date='FORM')
add(489,[454,470],'stated without proof','B','An A-submersive quotient determines the vertical tangent subbundle, which is involutive; in the ambient formal category its quotient is locally the formal Frobenius first-integral space. Bolsinov–Zuev Theorem2 verifies the converse over a characteristic-zero field for a regular distribution. The forward A-structure statement still uses the differential/chart axioms.',['P4_BolsinovZuev2009'],['P4-S13'],statement='A smooth formal submersion defines an involutive constant-rank vertical distribution; over a characteristic-zero field a constant-rank involutive formal distribution has a smooth formal quotient locally.',comp='proof_audit.md §7: bracket of vertical derivations and first-integral coordinate criterion.',date='FORM')

if __name__=='__main__':
 ids=[c['id'] for c in claims];assert len(ids)==len(set(ids))
 (OUT/'claims.json').write_text(json.dumps(claims,ensure_ascii=False,indent=2)+'\n')
 print(f'{len(claims)} individually authored core mathematical claim records saved.')
